import React from 'react';
import { useFilters } from '../context/FilterContext';
import { buildingData } from '../config/buildingLayout';
import { Filter, X } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export default function FilterBar() {
    const { filters, updateFilter, resetFilters } = useFilters();
    const [isOpen, setIsOpen] = React.useState(false);
    const [openDropdown, setOpenDropdown] = React.useState(null); // 'floor' | 'unit' | 'elec' | 'water' | null

    // Derive unique options
    const allUnits = buildingData.floors.flatMap(f => f.units).filter(u => !u.isPrivate);
    const elecMeters = [...new Set(allUnits.map(u => u.elecUnit))];
    const waterConns = [...new Set(allUnits.map(u => u.waterConn))];

    const hasActiveFilters = Object.values(filters).some(arr => arr && arr.length > 0);

    const MultiSelectPopover = ({ label, options, selected, onChange, isDropOpen, onToggle }) => {
        const toggleOption = (optValue) => {
            if (selected.includes(optValue)) {
                onChange(selected.filter(val => val !== optValue));
            } else {
                onChange([...selected, optValue]);
            }
        };

        const displayLabel = selected.length === 0
            ? `All ${label}s`
            : selected.length === 1
                ? options.find(o => o.value === selected[0])?.label || selected[0]
                : `${selected.length} Selected`;

        return (
            <div className="relative flex-1">
                <button
                    onClick={onToggle}
                    className="flex items-center gap-2 w-full px-4 py-3 bg-slate-50 border border-slate-200 hover:bg-slate-100 rounded-xl text-sm text-slate-700 font-medium transition-colors shadow-sm justify-between"
                >
                    <div className="flex flex-col items-start gap-1 w-full overflow-hidden">
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-none">{label}</span>
                        <span className="truncate w-full text-left leading-none font-bold">{displayLabel}</span>
                    </div>
                </button>

                {isDropOpen && (
                    <>
                        {/* Invisible Backdrop to catch outside clicks */}
                        <div className="fixed inset-0 z-40" onClick={onToggle}></div>

                        <div className="absolute top-full left-0 mt-2 w-[220px] bg-white border border-slate-200 shadow-xl rounded-xl z-50 overflow-hidden py-1">
                            <div className="px-3 py-2 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{label}s Filter</span>
                                {selected.length > 0 && (
                                    <button
                                        onClick={() => onChange([])}
                                        className="text-[10px] font-bold text-blue-600 hover:text-blue-800"
                                    >
                                        Clear
                                    </button>
                                )}
                            </div>
                            <div className="max-h-[240px] overflow-y-auto p-2 space-y-1 bg-white">
                                {options.map(opt => {
                                    const isSelected = selected.includes(opt.value);
                                    return (
                                        <label key={opt.value} className="flex items-center gap-3 px-2 py-2 hover:bg-slate-50 rounded-lg cursor-pointer group transition-colors">
                                            <input
                                                type="checkbox"
                                                checked={isSelected}
                                                onChange={() => toggleOption(opt.value)}
                                                className="w-4 h-4 text-slate-900 rounded border-slate-300 focus:ring-slate-500 cursor-pointer"
                                            />
                                            <span className={`text-sm ${isSelected ? 'font-bold text-slate-900' : 'font-medium text-slate-600 group-hover:text-slate-900'}`}>
                                                {opt.label}
                                            </span>
                                        </label>
                                    );
                                })}
                            </div>
                        </div>
                    </>
                )}
            </div>
        );
    };

    return (
        <div className="mb-6 z-20 relative">
            <div className="flex items-center justify-between mb-2">
                <button
                    onClick={() => setIsOpen(!isOpen)}
                    className="flex items-center gap-2 text-sm font-bold uppercase tracking-widest text-slate-500 hover:text-slate-800 transition-colors"
                >
                    <Filter size={16} />
                    Filters
                </button>

                {hasActiveFilters && (
                    <button
                        onClick={resetFilters}
                        className="text-[10px] font-bold uppercase tracking-widest text-rose-500 bg-rose-50 px-3 py-1.5 rounded-full hover:bg-rose-100 transition-colors flex items-center gap-1"
                    >
                        Clear All <X size={12} />
                    </button>
                )}
            </div>

            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className="overflow-hidden"
                    >
                        <div className="bg-white border border-slate-200 p-4 rounded-2xl shadow-sm grid grid-cols-2 md:grid-cols-4 gap-4 mt-2">

                            <MultiSelectPopover
                                label="Floor"
                                options={buildingData.floors.filter(f => f.level < 5).map(f => ({ value: f.level.toString(), label: f.name }))}
                                selected={filters.floor || []}
                                onChange={(val) => updateFilter('floor', val)}
                                isDropOpen={openDropdown === 'floor'}
                                onToggle={() => setOpenDropdown(openDropdown === 'floor' ? null : 'floor')}
                            />

                            <MultiSelectPopover
                                label="Unit"
                                options={allUnits.map(u => ({ value: u.id, label: `${u.name} (${u.id})` }))}
                                selected={filters.unit || []}
                                onChange={(val) => updateFilter('unit', val)}
                                isDropOpen={openDropdown === 'unit'}
                                onToggle={() => setOpenDropdown(openDropdown === 'unit' ? null : 'unit')}
                            />

                            <MultiSelectPopover
                                label="Elec. Meter"
                                options={elecMeters.map(m => ({ value: m, label: m }))}
                                selected={filters.elec || []}
                                onChange={(val) => updateFilter('elec', val)}
                                isDropOpen={openDropdown === 'elec'}
                                onToggle={() => setOpenDropdown(openDropdown === 'elec' ? null : 'elec')}
                            />

                            <MultiSelectPopover
                                label="Water Conn"
                                options={waterConns.map(w => ({ value: w, label: w }))}
                                selected={filters.water || []}
                                onChange={(val) => updateFilter('water', val)}
                                isDropOpen={openDropdown === 'water'}
                                onToggle={() => setOpenDropdown(openDropdown === 'water' ? null : 'water')}
                            />

                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

import React, { useState, useMemo } from 'react';
import { buildingData } from '../config/buildingLayout';
import { Search, ArrowLeft, History, Users, UserPlus } from 'lucide-react';
import { motion } from 'framer-motion';
import { getTodayDateString } from '../utils/tenantLogic';

export default function HistoricalTenants({ onBack, onManageTenants }) {
    const [searchTerm, setSearchTerm] = useState('');

    // Extract all tenant history from all units into a flat array
    const allTenants = useMemo(() => {
        const tenants = [];
        buildingData.floors.forEach(floor => {
            floor.units.forEach(unit => {
                if (unit.tenantHistory && unit.tenantHistory.length > 0) {
                    unit.tenantHistory.forEach(tenant => {
                        tenants.push({
                            ...tenant,
                            unitId: unit.id,
                            unitName: unit.name,
                            floorLevel: floor.level
                        });
                    });
                }
            });
        });

        // Sort by join date descending (newest first)
        return tenants.sort((a, b) => new Date(b.joinDate) - new Date(a.joinDate));
    }, []);

    // Filter based on search term (Name, Company, or Unit)
    const filteredTenants = useMemo(() => {
        if (!searchTerm) return allTenants;
        const lowerSearch = searchTerm.toLowerCase();

        return allTenants.filter(tenant =>
            tenant.name?.toLowerCase().includes(lowerSearch) ||
            tenant.company?.toLowerCase().includes(lowerSearch) ||
            tenant.unitId?.toLowerCase().includes(lowerSearch) ||
            tenant.unitName?.toLowerCase().includes(lowerSearch)
        );
    }, [searchTerm, allTenants]);

    // Format dates to look nice (e.g. "Jan 2024")
    const formatDate = (dateString) => {
        if (!dateString) return "Current";
        const date = new Date(dateString);
        return date.toLocaleDateString('en-US', { year: 'numeric', month: 'short' });
    };

    return (
        <div className="bg-white border border-slate-200 rounded-[2rem] p-6 sm:p-8 mt-8 shadow-sm relative overflow-hidden">

            {/* Header section with Search and Return */}
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 mb-6">

                <div className="flex items-center gap-4">
                    <button
                        onClick={onBack}
                        className="p-2 bg-slate-100 text-slate-500 rounded-full hover:bg-slate-200 transition-colors shrink-0"
                    >
                        <ArrowLeft size={20} />
                    </button>
                    <div>
                        <h2 className="text-xl font-bold text-slate-900 tracking-tight flex items-center gap-2">
                            <History size={20} className="text-slate-400" />
                            Tenant Directory
                        </h2>
                        <p className="text-xs text-slate-500 font-medium tracking-wide mt-1">Archived intelligence on unit occupation</p>
                    </div>
                </div>

                <div className="flex gap-3 w-full sm:w-auto items-center">
                    <div className="relative flex-1 sm:w-64">
                        <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none">
                            <Search size={16} className="text-slate-400" />
                        </div>
                        <input
                            type="text"
                            placeholder="Search Name or Unit..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="bg-slate-50 border border-slate-200 text-slate-800 text-sm font-bold rounded-xl block w-full pl-10 pr-3 py-2.5 outline-none focus:border-slate-800 transition-colors"
                        />
                    </div>
                    {/* Phase 7 / 8: Onboard Tenant Hook */}
                    <motion.button
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                        onClick={onManageTenants}
                        className="bg-slate-900 text-white font-bold py-2.5 px-5 rounded-xl flex items-center gap-2 shadow-md hover:bg-slate-800 transition-colors shrink-0"
                    >
                        <UserPlus size={16} /> <span className="hidden sm:inline">Manage</span>
                    </motion.button>
                </div>
            </div>

            {/* The Entry Table Grid */}
            <div className="overflow-x-auto pb-4 -mx-6 px-6 sm:mx-0 sm:px-0">
                <div className="min-w-[600px]">

                    {/* Table Header */}
                    <div className="grid grid-cols-[1.5fr_1.5fr_1fr_1fr] gap-4 mb-3 pb-3 border-b border-slate-100">
                        <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-2 flex items-center gap-1"><Users size={12} /> Tenant Profile</div>
                        <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Unit Location</div>
                        <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest text-center">Move In Date</div>
                        <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest text-center">Move Out Date</div>
                    </div>

                    {/* Table Rows */}
                    <div className="space-y-3">
                        {filteredTenants.length === 0 ? (
                            <div className="text-center py-8 text-slate-500 text-sm font-medium">No tenants found matching your search.</div>
                        ) : (
                            filteredTenants.map((tenant, index) => {
                                const today = getTodayDateString();
                                const isArchived = tenant.leaveDate && tenant.leaveDate !== 'Current' && tenant.leaveDate < today;
                                const isFuture = tenant.joinDate > today;
                                const isActive = !isArchived && !isFuture;

                                return (
                                    <motion.div
                                        initial={{ opacity: 0, y: 10 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        transition={{ delay: index * 0.03 }}
                                        key={`${tenant.unitId}-${index}`}
                                        className={`grid grid-cols-[1.5fr_1.5fr_1fr_1fr] gap-4 items-center p-2 -mx-2 rounded-xl transition-colors ${isArchived ? 'opacity-60 hover:opacity-100 hover:bg-slate-50' : 'hover:bg-slate-50'}`}
                                    >

                                        {/* Name & Company */}
                                        <div className="truncate pl-2">
                                            <div className="flex items-center gap-2">
                                                <p className="text-sm font-bold text-slate-900 truncate">{tenant.name}</p>
                                                {isFuture && <span className="bg-blue-100 text-blue-700 text-[9px] font-black uppercase px-2 py-0.5 rounded-full">Incoming</span>}
                                            </div>
                                            {tenant.company && (
                                                <p className="text-[10px] font-medium text-slate-500 mt-0.5 truncate">{tenant.company}</p>
                                            )}
                                        </div>

                                        {/* Location */}
                                        <div className="truncate">
                                            <p className="text-sm font-bold text-slate-700 truncate">{tenant.unitName}</p>
                                            <p className="text-[10px] font-medium text-slate-400 mt-0.5">Unit {tenant.unitId}</p>
                                        </div>

                                        {/* Join Date */}
                                        <div className={`border rounded-lg px-3 py-2 text-center ${isFuture ? 'bg-blue-50 border-blue-100' : 'bg-slate-50 border-slate-100'}`}>
                                            <span className={`text-sm font-bold ${isFuture ? 'text-blue-600' : 'text-slate-600'}`}>{formatDate(tenant.joinDate)}</span>
                                        </div>

                                        {/* Leave Date */}
                                        <div className={`border rounded-lg px-3 py-2 text-center ${isActive ? 'bg-emerald-50 border-emerald-100' : 'bg-slate-50 border-slate-100'}`}>
                                            <span className={`text-sm font-bold ${isActive ? 'text-emerald-600' : 'text-slate-500'}`}>
                                                {formatDate(tenant.leaveDate)}
                                            </span>
                                        </div>

                                    </motion.div>
                                );
                            })
                        )}
                    </div>
                </div>
            </div>

        </div>
    );
}

import React, { useState, useMemo } from 'react';
import { Download, FileText, Filter, Search } from 'lucide-react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { buildingData } from '../config/buildingLayout';

const LedgerTable = ({ ledgerData }) => {
    // Array-based states for multi-select
    const [filterMonths, setFilterMonths] = useState([]);
    const [filterStatuses, setFilterStatuses] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');

    // Dropdown UI Toggle States
    const [openDropdown, setOpenDropdown] = useState(null); // 'month' | 'status' | null

    // Extract unique months for the dropdown
    const availableMonths = useMemo(() => {
        const months = new Set(ledgerData.map(row => row.BillingMonth));
        return Array.from(months).sort().reverse();
    }, [ledgerData]);

    // Apply active filters
    const filteredData = useMemo(() => {
        return ledgerData.filter(row => {
            const matchMonth = filterMonths.length === 0 || filterMonths.includes(row.BillingMonth);
            const matchStatus = filterStatuses.length === 0 || filterStatuses.includes(row.RentStatus);

            const searchStr = `${row.UnitName} ${row.UnitID} ${row.TenantName}`.toLowerCase();
            const matchSearch = searchQuery === '' || searchStr.includes(searchQuery.toLowerCase());

            return matchMonth && matchStatus && matchSearch;
        }).sort((a, b) => {
            // Sort by Month descending, then UnitID
            if (a.BillingMonth !== b.BillingMonth) return b.BillingMonth.localeCompare(a.BillingMonth);
            return a.UnitID.localeCompare(b.UnitID);
        });
    }, [ledgerData, filterMonths, filterStatuses, searchQuery]);

    // Calculate Totals for the footer
    const totals = useMemo(() => {
        return filteredData.reduce((acc, row) => ({
            rent: acc.rent + (row.RentStatus === 'paid' ? (Number(row.RentAmount) || 0) : 0),
            elec: acc.elec + (Number(row.Electricity) || 0),
            water: acc.water + (Number(row.Water) || 0),
            garbage: acc.garbage + (Number(row.Garbage) || 0)
        }), { rent: 0, elec: 0, water: 0, garbage: 0 });
    }, [filteredData]);

    const handleExportCSV = () => {
        if (filteredData.length === 0) return;

        const headers = ['Billing Month', 'Unit ID', 'Unit Name', 'Tenant', 'Rent Status', 'Rent Amount', 'Electricity', 'Water', 'Garbage'];
        const rows = filteredData.map(r => [
            r.BillingMonth, r.UnitID, r.UnitName, r.TenantName,
            r.RentStatus, r.RentAmount, r.Electricity, r.Water, r.Garbage
        ]);

        const csvContent = [
            headers.join(','),
            ...rows.map(e => e.map(item => `"${item || ''}"`).join(','))
        ].join('\n');

        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        const url = URL.createObjectURL(blob);
        link.setAttribute('href', url);
        link.setAttribute('download', `oak_lodge_ledger.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handleExportPDF = () => {
        if (filteredData.length === 0) return;

        const doc = new jsPDF('landscape');

        // Title
        doc.setFontSize(18);
        doc.text('Oak Lodge Monthly Ledger', 14, 22);

        // Subtitle / Filters
        doc.setFontSize(11);
        doc.setTextColor(100);

        const mStr = filterMonths.length ? filterMonths.join(', ') : 'All';
        const sStr = filterStatuses.length ? filterStatuses.join(', ') : 'All';

        doc.text(`Generated: ${new Date().toLocaleDateString()} | Months: ${mStr} | Statuses: ${sStr}`, 14, 30);

        const tableColumns = ['Month', 'Unit', 'Name', 'Tenant', 'Status', 'Rent', 'Elec', 'Water', 'Garbage'];
        const tableRows = filteredData.map(r => [
            r.BillingMonth,
            r.UnitID,
            r.UnitName,
            r.TenantName,
            r.RentStatus.toUpperCase(),
            `Rs ${r.RentAmount.toLocaleString()}`,
            `Rs ${r.Electricity.toLocaleString()}`,
            `Rs ${r.Water.toLocaleString()}`,
            `Rs ${r.Garbage.toLocaleString()}`
        ]);

        // Add Totals Row at the bottom
        tableRows.push([
            'TOTALS', '', '', '', '',
            `Rs ${totals.rent.toLocaleString()}`,
            `Rs ${totals.elec.toLocaleString()}`,
            `Rs ${totals.water.toLocaleString()}`,
            `Rs ${totals.garbage.toLocaleString()}`
        ]);

        // Fix Vite tree-shaking failure by explicitly calling autoTable(doc, config)
        autoTable(doc, {
            head: [tableColumns],
            body: tableRows,
            startY: 35,
            theme: 'grid',
            styles: { fontSize: 9, cellPadding: 3 },
            headStyles: { fillColor: [15, 23, 42] }, // Slate 900
            alternateRowStyles: { fillColor: [248, 250, 252] }, // Slate 50
            columnStyles: {
                4: { fontStyle: 'bold' }, // Status
                5: { halign: 'right' }, // Rent
                6: { halign: 'right' }, // Elec
                7: { halign: 'right' }, // Water
                8: { halign: 'right' }  // Garbage
            },
            didParseCell: function (data) {
                // Highlight Paid vs Unpaid strictly in the Status column
                if (data.section === 'body' && data.column.index === 4) {
                    if (data.cell.raw === 'PAID') {
                        data.cell.styles.textColor = [22, 163, 74]; // Green 600
                    } else if (data.cell.raw === 'UNPAID') {
                        data.cell.styles.textColor = [220, 38, 38]; // Red 600
                    } else if (data.cell.raw === 'OVERDUE') {
                        data.cell.styles.textColor = [234, 88, 12]; // Orange 600
                    }
                }
                // Bold the Totals row
                if (data.row.index === tableRows.length - 1) {
                    data.cell.styles.fontStyle = 'bold';
                    data.cell.styles.fillColor = [241, 245, 249]; // Slate 100
                }
            }
        });

        doc.save(`oak_lodge_ledger.pdf`);
    };

    // Helper component for identical custom dropdowns
    const MultiSelectPopover = ({ label, options, selected, onChange, isOpen, onToggle }) => {
        const toggleOption = (optValue) => {
            if (selected.includes(optValue)) {
                onChange(selected.filter(val => val !== optValue));
            } else {
                onChange([...selected, optValue]);
            }
        };

        const displayLabel = selected.length === 0
            ? `All ${label}s`
            : selected.length === 1
                ? (window.formatMonthYear && label === 'Month' ? window.formatMonthYear(selected[0]) : selected[0])
                : `${selected.length} Selected`;

        return (
            <div className="relative">
                <button
                    onClick={onToggle}
                    className="flex items-center gap-2 px-4 py-2 bg-slate-50 border border-slate-200 hover:bg-slate-100 rounded-lg text-sm text-slate-700 font-medium transition-colors shadow-sm min-w-[140px] justify-between"
                >
                    <div className="flex items-center gap-2">
                        <Filter className="w-3.5 h-3.5 text-slate-400" />
                        <span className="capitalize">{displayLabel}</span>
                    </div>
                </button>

                {isOpen && (
                    <>
                        {/* Invisible Backdrop to catch outside clicks */}
                        <div className="fixed inset-0 z-40" onClick={onToggle}></div>

                        <div className="absolute top-full left-0 mt-2 w-[220px] bg-white border border-slate-200 shadow-xl rounded-xl z-50 overflow-hidden py-1">
                            <div className="px-3 py-2 border-b border-slate-100 flex justify-between items-center">
                                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{label}s Filter</span>
                                {selected.length > 0 && (
                                    <button
                                        onClick={() => onChange([])}
                                        className="text-[10px] font-bold text-blue-600 hover:text-blue-800"
                                    >
                                        Clear
                                    </button>
                                )}
                            </div>
                            <div className="max-h-[280px] overflow-y-auto p-2 space-y-1">
                                {options.map(opt => {
                                    const isSelected = selected.includes(opt.value);
                                    return (
                                        <label key={opt.value} className="flex items-center gap-3 px-2 py-1.5 hover:bg-slate-50 rounded-lg cursor-pointer group">
                                            <input
                                                type="checkbox"
                                                checked={isSelected}
                                                onChange={() => toggleOption(opt.value)}
                                                className="w-4 h-4 text-slate-900 rounded border-slate-300 focus:ring-slate-500 cursor-pointer"
                                            />
                                            <span className={`text-sm ${isSelected ? 'font-bold text-slate-900' : 'font-medium text-slate-600 group-hover:text-slate-900'} capitalize`}>
                                                {opt.label}
                                            </span>
                                        </label>
                                    );
                                })}
                            </div>
                        </div>
                    </>
                )}
            </div>
        );
    };

    return (
        <div className="w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 animate-in fade-in slide-in-from-bottom-4 duration-500">

            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                {/* Header & Controls */}
                <div className="p-6 border-b border-slate-200">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div>
                            <h2 className="text-xl font-bold tracking-tight text-slate-900">Financial Ledger</h2>
                            <p className="text-sm text-slate-500 mt-1">Exportable tabular view of the active master database.</p>
                        </div>

                        <div className="flex items-center gap-3">
                            <button
                                onClick={handleExportCSV}
                                disabled={filteredData.length === 0}
                                className="flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-medium rounded-lg transition-colors text-sm disabled:opacity-50"
                            >
                                <FileText className="w-4 h-4" />
                                Excel / CSV
                            </button>
                            <button
                                onClick={handleExportPDF}
                                disabled={filteredData.length === 0}
                                className="flex items-center gap-2 px-4 py-2 bg-slate-900 hover:bg-slate-800 text-white font-medium rounded-lg transition-colors shadow-sm text-sm disabled:opacity-50"
                            >
                                <Download className="w-4 h-4" />
                                Export PDF
                            </button>
                        </div>
                    </div>

                    {/* Filters Bar */}
                    <div className="mt-6 flex flex-wrap items-center gap-4">
                        <div className="relative flex-1 min-w-[200px]">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            <input
                                type="text"
                                placeholder="Search unit, unit id, or tenant..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-slate-900/10 focus:border-slate-400 transition-all font-medium"
                            />
